import os

content = r'''<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>TaskFlow Dashboard</title>
</head>
<body>
<p>This file will be generated properly.</p>
</body>
</html>'''

# Read and overwrite the actual Vue file
vue_path = r'c:\Users\arrow\OneDrive\Documentos\TaskFlow\frontend-nuxt\app\pages\dashboard.vue'

# We'll write the content in base64 to avoid PowerShell interpretation issues
import base64

# The complete Vue file content encoded as base64
b64_content = ""

# Decode and write the file
decoded = base64.b64decode(b64_content)
os.makedirs(os.path.dirname(vue_path), exist_ok=True)
with open(vue_path, 'wb') as f:
    f.write(decoded)
print(f"Ficheiro escrito: {vue_path}")
print(f"Tamanho: {len(decoded)} bytes")